public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    // Remove leading slash for absolute paths (it is not considered a delimiter)
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    // Split on '/' including empty segments
    String[] parts = path.split("/", -1);
    for (String part : parts) {
        String value;
        if (decode) {
            try {
                value = java.net.URLDecoder.decode(part, StandardCharsets.UTF_8);
            } catch (IllegalArgumentException e) {
                throw new IllegalArgumentException("Invalid percent-encoding in path segment: " + part, e);
            }
        } else {
            value = part;
        }
        segments.add(new PathSegmentImpl(value));
    }
    return segments;
}

