    if (graph == null || vertices == null) {
        return false;
    }
    try {
        // Ensure every vertex in the set actually exists in the graph
        for (V v : vertices) {
            if (!graph.containsVertex(v)) {
                return false;
            }
        }
        // For every unordered pair of distinct vertices, the graph must contain an edge
        for (V u : vertices) {
            for (V v : vertices) {
                if (u.equals(v)) {
                    continue;
                }
                if (!graph.containsEdge(u, v)) {
                    return false;
                }
            }
        }
        return true; // All pairs are connected
    } catch (Exception e) {
        // Any unexpected error indicates we cannot confirm a clique
        return false;
    }
}

