    int pos = 0;
    if (descriptor.charAt(0) == '('){
        pos = 1;
        while (descriptor.length() > pos && descriptor.charAt(pos) != ')'){
            pos = readAndPop(descriptor, pos);
        }
        // Skip ')'
        pos++;
        // Consume return type (ignore it)
        if (pos < descriptor.length()){
            readAndPop(descriptor, pos);
        }
    } else {
        readAndPop(descriptor, pos);
    }
}

private int readAndPop(String descriptor, int index){
    // Skip array brackets
    while (descriptor.charAt(index) == '['){
        index++;
    }
    char type = descriptor.charAt(index);
    int slots = (type == 'J' || type == 'D') ? 2 : 1;
